insert into public.questions (id, command, prompt, options, correct_index, explanation) values
  (1, 'GRANT', 'O que o comando GRANT faz em um banco de dados?', array['Concede privilégios a um usuário ou papel.', 'Exclui todas as tabelas.', 'Remove um índice.'], 0, 'GRANT é um comando de controle de acesso (DCL): ele concede privilégios, como SELECT ou INSERT, a um usuário ou papel.'),
  (2, 'GRANT', 'Qual comando permite que o usuário ana consulte a tabela clientes?', array['REVOKE SELECT ON clientes FROM ana;', 'GRANT SELECT ON clientes TO ana;', 'CREATE INDEX ON clientes(ana);'], 1, 'A forma é GRANT privilégio ON objeto TO usuário. Aqui, ana recebe o privilégio SELECT na tabela clientes.'),
  (3, 'GRANT', 'Depois de GRANT INSERT, UPDATE ON pedidos TO vendas; o que o papel vendas pode fazer?', array['Apagar a tabela pedidos.', 'Criar uma cópia da tabela.', 'Inserir e atualizar dados em pedidos.'], 2, 'Só os privilégios listados são concedidos: INSERT e UPDATE. Apagar a tabela ou fazer outras operações exigiria outros privilégios.'),
  (4, 'GRANT', 'Qual é a vantagem de conceder privilégios a um papel (role) em vez de a cada usuário?', array['Facilita administrar as permissões de vários usuários de uma vez.', 'Deixa o banco automaticamente mais rápido.', 'Impede qualquer usuário de acessar os dados.'], 0, 'Com papéis, você concede o privilégio uma vez e depois associa os usuários ao papel. Isso organiza e simplifica a manutenção da segurança.'),
  (5, 'GRANT', 'Qual princípio de segurança recomenda conceder ao usuário apenas as permissões de que ele precisa?', array['Normalização.', 'Redundância.', 'Privilégio mínimo.'], 2, 'Privilégio mínimo reduz o estrago possível se uma conta for usada de forma indevida ou por engano. Use GRANT com cuidado.'),
  (6, 'GRANT', 'Em muitos SGBDs, o que a cláusula WITH GRANT OPTION permite?', array['Que o privilégio expire em 24 horas.', 'Que quem recebeu o privilégio possa repassá-lo a outros usuários.', 'Que o usuário apague o banco inteiro.'], 1, 'WITH GRANT OPTION deixa o destinatário conceder o mesmo privilégio a terceiros. Por isso deve ser usada com muito critério.'),
  (7, 'REVOKE', 'Para que serve o comando REVOKE?', array['Criar uma tabela.', 'Retirar privilégios concedidos anteriormente.', 'Aumentar a memória RAM.'], 1, 'REVOKE é o oposto de GRANT: retira privilégios que já tinham sido concedidos a um usuário ou papel.'),
  (8, 'REVOKE', 'Qual comando retira de ana a permissão de ler a tabela clientes?', array['REVOKE SELECT ON clientes FROM ana;', 'GRANT SELECT ON clientes TO ana;', 'DROP INDEX clientes;'], 0, 'A forma é REVOKE privilégio ON objeto FROM usuário. Repare que REVOKE usa FROM, enquanto GRANT usa TO.'),
  (9, 'REVOKE', 'Depois de REVOKE INSERT ON pedidos FROM vendas; o que acontece?', array['A tabela pedidos é apagada.', 'Todos os dados de pedidos são removidos.', 'O papel vendas perde a permissão de inserir; a tabela e os dados continuam.'], 2, 'REVOKE mexe somente nas permissões. A tabela e os dados não são afetados.'),
  (10, 'REVOKE', 'Em um REVOKE, quem aparece depois da palavra FROM?', array['A tabela afetada.', 'O usuário ou papel que perde o privilégio.', 'O nome do índice.'], 1, 'Depois do FROM vem o usuário ou papel que perderá o privilégio. A tabela aparece depois do ON.'),
  (11, 'REVOKE', 'Um funcionário mudou de setor e não deve mais ver dados financeiros. Qual é a ação mais adequada?', array['Revogar os privilégios que ele não precisa mais.', 'Dar a ele privilégios de administrador.', 'Criar um índice em todas as tabelas.'], 0, 'Manter permissões antigas viola o privilégio mínimo. Revogar o que não é mais necessário é uma boa prática de segurança.'),
  (12, 'REVOKE', 'GRANT e REVOKE pertencem a qual grupo de comandos da SQL?', array['DML (manipulação de dados).', 'DQL (consulta de dados).', 'DCL (controle de dados).'], 2, 'DCL (Data Control Language) cuida de permissões e acesso. GRANT e REVOKE são os principais comandos dela.'),
  (13, 'CREATE INDEX', 'Qual é o principal objetivo de criar um índice em uma tabela?', array['Acelerar determinadas consultas (buscas).', 'Criptografar os dados.', 'Conceder permissões.'], 0, 'Índices podem acelerar consultas, mas ocupam espaço e têm custo de manutenção. Não são grátis.'),
  (14, 'CREATE INDEX', 'Qual comando cria um índice na coluna email da tabela clientes?', array['GRANT INDEX ON clientes(email);', 'CREATE INDEX idx_email ON clientes(email);', 'ADD ROW email INTO clientes;'], 1, 'A forma é CREATE INDEX nome ON tabela(coluna). O índice ajuda consultas que filtram ou ordenam por email.'),
  (15, 'CREATE INDEX', 'Qual é uma desvantagem de criar índices em excesso?', array['Eles impedem o uso de SELECT.', 'Eles removem privilégios dos usuários.', 'Ocupam espaço e deixam INSERT, UPDATE e DELETE mais custosos.'], 2, 'A cada alteração na tabela, os índices também precisam ser atualizados. Por isso, crie índices só onde há ganho real.'),
  (16, 'CREATE INDEX', 'Em qual tipo de coluna um índice costuma trazer mais benefício?', array['Colunas muito usadas em WHERE, JOIN ou ORDER BY.', 'Colunas que nunca são consultadas.', 'Apenas colunas de tabelas vazias.'], 0, 'Índices ajudam onde o banco precisa localizar ou ordenar dados com frequência. Colunas nunca consultadas só geram custo.'),
  (17, 'CREATE INDEX', 'O que acontece com um índice quando novos registros são inseridos na tabela?', array['Nada: o índice nunca muda.', 'O índice também precisa ser atualizado, o que tem um custo.', 'O índice é apagado automaticamente.'], 1, 'Manter o índice atualizado é o custo de manutenção. Tabelas com muita escrita sofrem mais com excesso de índices.'),
  (18, 'CREATE INDEX', 'Qual comando cria um índice único (sem valores repetidos) na coluna cpf?', array['CREATE INDEX UNIQUE cpf;', 'GRANT UNIQUE ON cpf;', 'CREATE UNIQUE INDEX idx_cpf ON alunos(cpf);'], 2, 'CREATE UNIQUE INDEX impede valores repetidos na coluna e, de quebra, pode acelerar buscas por ela.'),
  (19, 'DROP INDEX', 'O que faz o comando DROP INDEX?', array['Cria um índice novo.', 'Remove um índice existente.', 'Concede privilégios a um usuário.'], 1, 'DROP INDEX remove um índice existente. Isso pode prejudicar o desempenho de algumas consultas que dependiam dele.'),
  (20, 'DROP INDEX', 'Qual comando remove o índice chamado idx_email?', array['DROP INDEX idx_email;', 'DROP TABLE idx_email;', 'REVOKE INDEX idx_email;'], 0, 'DROP INDEX nome remove o índice. Em alguns SGBDs (como MySQL e SQL Server) é preciso informar também a tabela com ON.'),
  (21, 'DROP INDEX', 'Ao executar DROP INDEX, os dados da tabela são apagados?', array['Sim, todos os dados.', 'Sim, apenas as colunas indexadas.', 'Não: só o índice é removido; os dados da tabela permanecem.'], 2, 'O índice é uma estrutura auxiliar. Removê-lo não apaga as linhas da tabela, mas algumas consultas podem ficar mais lentas.'),
  (22, 'DROP INDEX', 'Por que pode valer a pena remover um índice que quase nunca é usado?', array['Porque aumenta os privilégios do usuário.', 'Porque reduz o espaço ocupado e o custo de INSERT, UPDATE e DELETE.', 'Porque cria uma cópia da tabela.'], 1, 'Índices sem uso só geram custo de espaço e de manutenção. Removê-los pode melhorar as operações de escrita.'),
  (23, 'DROP INDEX', 'Qual risco existe ao remover um índice que é muito usado pelas consultas?', array['Algumas consultas podem ficar mais lentas.', 'Os usuários perdem o acesso ao banco.', 'A tabela fica bloqueada para sempre.'], 0, 'Sem o índice, o banco pode precisar varrer a tabela inteira. Antes de remover, confirme se ele não é importante.'),
  (24, 'DROP INDEX', 'Como decidir se vale a pena remover um índice?', array['Apagar o de nome mais comprido.', 'Remover todos para ver o que acontece.', 'Verificar se as consultas o utilizam (por exemplo, com EXPLAIN ou estatísticas de uso).'], 2, 'Decisões de desempenho devem se basear em evidências: veja o plano de execução (EXPLAIN) e as estatísticas de uso do índice.')
