-- =====================================================================
-- BOSS BATTLE SQL — 02_questions.sql
-- Rode DEPOIS do 01_schema.sql. Pode rodar de novo sem medo: atualiza as perguntas.
-- Gerado a partir de questions.js (24 perguntas, 6 por comando).
-- =====================================================================

on conflict (id) do update set
  command = excluded.command, prompt = excluded.prompt, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation;

select command, count(*) as perguntas from public.questions group by command order by command;
